'use client';
import { useId, useState, type CSSProperties } from 'react';
import { cx } from '../lib/cx';
import { useTween } from '../lib/hooks';
import { Seg, Swap } from '../lib/motion';
import '../designme.css';
import './radial-goals.css';

export interface RadialGoal {
  key: string;
  /** Like "Support agent" */
  label: string;
  /** What it counts, like "tickets" */
  unit: string;
  value: number;
  target: number;
  /** Defaults to the chart palette in order */
  color?: string;
}

export interface RadialGoalsProps<R extends string = string> {
  /** Two to five goals, outermost first. Three read best: the fewer the rings, the thicker they are */
  goals: RadialGoal[];
  title?: string;
  /** The line under the title, like the period it covers ("This week"). Leave it out for none */
  subtitle?: string;
  /** A switch for the period, like Week and Month */
  ranges?: { value: R; label: string }[];
  range?: R;
  onRangeChange?: (range: R) => void;
  className?: string;
}

const PAL = ['var(--dm-c1)', 'var(--dm-c2)', 'var(--dm-c3)', 'var(--dm-c4)', 'var(--dm-c5)'];
const pc = (x: number) => Math.round(x * 100) + '%';

/** Concentric rings, one per agent, each its share of its own target. What is still to go is hatched in the ring's colour; past
    the target the ring goes round again over its start in a deeper shade, with a small cap where it ends. */
export function RadialGoals<R extends string = string>({ goals, title = 'Agent goals', subtitle, ranges, range, onRangeChange, className }: RadialGoalsProps<R>) {
  const [focus, setFocus] = useState(-1);
  // the rings share the band from the outer edge (85) to the readout in the middle (34) with a 4 unit gap between them, so
  // three goals get rings 14 units wide; never wider than 16
  const W = Math.min(16, (51 - 4 * (goals.length - 1)) / Math.max(1, goals.length));
  const RAD = goals.map((_, i) => 85 - W / 2 - i * (W + 4));
  const share = (g: RadialGoal) => g.target ? g.value / g.target : 0;
  const overall = goals.reduce((t, g) => t + share(g), 0) / Math.max(1, goals.length);
  const mid = useTween(focus < 0 ? overall : share(goals[focus]), 600, 0);
  // each ring's hatch is a pattern of its own, named after this chart so two charts on a page keep theirs apart
  const uid = useId().replace(/[^\w-]/g, '');
  return (
    <div data-dm="" className={cx('dm-rgx dm-panel', className)}>
      <div className="dm-rgx-h">
        <div className="dm-rgx-t"><b>{title}</b>{subtitle && <Swap className="dm-muted dm-rgx-sub">{subtitle}</Swap>}</div>
        {ranges && range !== undefined && onRangeChange && <Seg className="dm-rgx-sg" label="Range" options={ranges} value={range} onChange={onRangeChange} />}
      </div>
      <div className="dm-rgx-b">
        <div className={cx('dm-rgx-ring', focus >= 0 && 'dm-hov')}>
          <svg viewBox="0 0 180 180" aria-hidden="true" style={{ ['--dm-rw' as string]: W } as CSSProperties}>
            <defs>
              {goals.map((g, i) => (
                <pattern key={g.key} id={`${uid}-${i}`} className="dm-rgx-hp" style={{ ['--dm-rc' as string]: g.color ?? PAL[i % PAL.length] } as CSSProperties}
                  patternUnits="userSpaceOnUse" width={4} height={4} patternTransform="rotate(45)"><rect width={1.3} height={4} /></pattern>
              ))}
            </defs>
            {goals.map((g, i) => { const s = share(g), c = g.color ?? PAL[i % PAL.length];
              return (
                <g key={g.key} className={cx(i === focus && 'dm-on', s > 1 && 'dm-lap')} style={{ ['--dm-rc' as string]: c } as CSSProperties} onPointerEnter={e => { if (e.pointerType !== 'touch') setFocus(i); }} onPointerLeave={() => setFocus(-1)}>
                  <circle className="dm-tr" cx={90} cy={90} r={RAD[i]} />
                  {/* what is still to go, from the share to the target, hatched in the ring's colour */}
                  <circle className="dm-rm" cx={90} cy={90} r={RAD[i]} pathLength={100} strokeDasharray={`${Math.max(0, 1 - s) * 100} 100`} strokeDashoffset={-Math.min(1, s) * 100} style={{ stroke: `url(#${uid}-${i})` }} />
                  <circle className="dm-fl" cx={90} cy={90} r={RAD[i]} pathLength={100} strokeDasharray={`${Math.max(0, Math.min(1, s) * 100 - .01)} 100`} />
                  {/* past the target the ring goes round again from the top in a deeper shade, and a cap sits where it ends */}
                  {/* under the lap's end only, a band of the surface a little wider than the ring, so the end cuts into the ring under it */}
                  <circle className="dm-ovb" cx={90} cy={90} r={RAD[i]} pathLength={100} strokeDasharray={`${Math.min(3, Math.max(0, s - 1) * 100)} 100`} strokeDashoffset={-Math.max(0, (s - 1) * 100 - 3)} />
                  <circle className="dm-ov" cx={90} cy={90} r={RAD[i]} pathLength={100} strokeDasharray={`${Math.max(0, s - 1) * 100} 100`} />
                  {/* the cap turns round the middle with the lap's end, so the two move together */}
                  <circle className="dm-mk" r={Math.max(2.5, W * .29)} cx={90 + RAD[i]} cy={90} style={{ transform: `rotate(${Math.max(0, s - 1) * 360}deg)` }} />
                </g>
              ); })}
          </svg>
          {/* the one big figure; what it is a share of is for screen readers only */}
          <div className="dm-rgx-c"><b className="dm-num">{pc(mid)}</b><span className="dm-rgx-cl">{focus < 0 ? 'of targets' : `of the ${goals[focus].label}'s target`}</span></div>
        </div>
        <div className="dm-rgx-lg">
          {goals.map((g, i) => { const s = share(g);
            return (
              <div key={g.key} className={cx('dm-rgx-r', i === focus && 'dm-on')} tabIndex={0} aria-label={`${g.label}: ${g.value} of ${g.target} ${g.unit}, ${pc(s)} of target`}
                onPointerEnter={e => { if (e.pointerType !== 'touch') setFocus(i); }} onPointerLeave={e => { if (!e.currentTarget.parentElement?.contains(document.activeElement)) setFocus(-1); }}
                onFocus={() => setFocus(i)} onBlur={() => setFocus(-1)}>
                <i style={{ background: g.color ?? PAL[i % PAL.length] }} /><span className="dm-n">{g.label}</span>
                <span className="dm-p dm-num">{s >= 1 ? <span className="dm-tag dm-ok">{pc(s)}</span> : pc(s)}</span>
                <span className="dm-v dm-num">{g.value.toLocaleString('en-US')} / {g.target.toLocaleString('en-US')} {g.unit}</span>
              </div>
            ); })}
        </div>
      </div>
      <div className="dm-rgx-sr"><table>
        <caption>{title}</caption>
        <thead><tr><th>Agent</th><th>Done</th><th>Target</th><th>Share</th></tr></thead>
        <tbody>{goals.map(g => <tr key={g.key}><th>{g.label}</th><td>{g.value} {g.unit}</td><td>{g.target}</td><td>{pc(share(g))}</td></tr>)}</tbody>
      </table></div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Radial goals ---------- */
/* one ring per agent, each its share of its own target, in the chart palette's colours in order on a neutral track. What is
   still to go, from the share to the target, is a fine diagonal hatch in the ring's colour over the track (owner, 20 Nov), so
   the gap reads at a glance; past the target the ring is whole and the extra goes round again over its start as a second lap
   in a deeper shade of its colour (a brighter one in dark), cutting into the ring under it, with a small cap where it ends.
   Everything moves with the ring as it draws. The middle is the one big number in the card (the type rules' exception for a
   data card's figure), with its words for screen readers only. The content sits 16px in from every edge: each row's mark sits
   on the content's left edge under the title and its share ends on the right edge, and its hover is a quiet fill that reaches
   out round them */
.dm-rgx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4);--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.dm-rgx-h{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
.dm-rgx-t{display:flex;flex-direction:column;font-size:13.5px;line-height:1.4}
.dm-rgx-t b{font-weight:500}
.dm-rgx-t .dm-muted{font-size:12px}
.dm-rgx-sg button{font-size:12px;height:26px;padding:0 10px}
.dm-rgx-b{display:flex;align-items:center;gap:var(--dm-s-5);flex-wrap:wrap;justify-content:center}
.dm-rgx-ring{position:relative;width:172px;height:172px;flex:none}
.dm-rgx-ring svg{width:100%;height:100%;transform:rotate(-90deg);overflow:visible}
.dm-rgx-ring circle{fill:none;stroke-width:var(--dm-rw,14);transition:opacity var(--dm-t-fast) var(--dm-ease)}
.dm-rgx-ring g{--dm-rgx-deep:color-mix(in oklab,var(--dm-rc) 70%,var(--dm-rgx-shade,#000))}
.dm-rgx-ring .dm-tr{stroke:var(--dm-chip)}
.dm-rgx-ring .dm-fl{stroke:var(--dm-rc)}
.dm-rgx-ring :is(.dm-fl,.dm-ov,.dm-ovb,.dm-rm){transition:stroke-dasharray .9s var(--dm-ease),stroke-dashoffset .9s var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
.dm-rgx-ring :is(.dm-fl,.dm-ov,.dm-ovb){stroke-linecap:round}
/* what is still to go: the ring's own colour as a fine diagonal hatch (each line a full-strength mark) over the track */
.dm-rgx-hp rect{fill:var(--dm-rc)}
/* the lap past the target, a deeper shade of the ring's colour; its end sits on a slightly wider band of the surface, so it
   cuts into the ring under it and reads as a second lap, and a small cap marks where it ends */
.dm-rgx-ring .dm-ov{stroke:var(--dm-rgx-deep)}
.dm-rgx-ring .dm-ovb{stroke:var(--dm-surface);stroke-width:calc(var(--dm-rw,14) * 1px + 3px)}
.dm-rgx-ring .dm-mk{fill:var(--dm-surface);stroke:var(--dm-rgx-deep);stroke-width:2.5;transform-box:view-box;transform-origin:90px 90px;transition:transform .9s var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
.dm-rgx-ring.dm-hov g:not(.dm-on) :is(.dm-fl,.dm-ov,.dm-mk,.dm-rm){opacity:.25}
:root[data-theme="dark"] .dm-rgx{--dm-rgx-shade:#fff}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-rgx{--dm-rgx-shade:#fff}}
/* a ring short of its target has no lap and no marker */
.dm-rgx-ring g:not(.dm-lap) :is(.dm-ov,.dm-ovb,.dm-mk){opacity:0!important}
.dm-rgx-c{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none;line-height:1.3;text-align:center}
/* the one big figure in the card: as large as the innermost ring comfortably holds, at the data card's weight */
.dm-rgx-c b{font-size:22px;font-weight:600;letter-spacing:-.03em;line-height:1}
.dm-rgx-c .dm-rgx-cl{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.dm-rgx-lg{flex:1 1 180px;min-width:0;display:flex;flex-direction:column;gap:2px;margin:-6px -8px}
.dm-rgx-r{display:grid;grid-template-columns:auto 1fr auto;column-gap:9px;row-gap:1px;align-items:center;width:100%;padding:6px var(--dm-s-2);border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));font-size:13px;text-align:left;transition:background-color var(--dm-t-fast) var(--dm-ease);cursor:default}
.dm-rgx-r.dm-on{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-rgx-r:hover{background:var(--dm-row)}}
.dm-rgx-r i{width:8px;height:8px;border-radius:50%}
.dm-rgx-r .dm-n{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-rgx-r .dm-p{font-size:12.5px;color:var(--dm-fg2);text-align:right}
.dm-rgx-r .dm-v{grid-column:2/4;font-size:12px;color:var(--dm-muted)}
.dm-rgx-r .dm-tag{height:18px;font-size:11px}
.dm-rgx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
.dm-rgx{container-type:inline-size}
@container (max-width:300px){.dm-rgx-lg{min-width:0}.dm-rgx-h{flex-wrap:wrap}}
.dm-rgx-sr table{table-layout:fixed;width:1px;border-collapse:collapse}
/* (the table is for screen readers only; its headings keep the type's 500 at most all the same) */
.dm-rgx-sr :is(th,caption){font-weight:500}

